        if a == b:
            return 0
        return 1 if a > b else -1

    @staticmethod
    def _add_abs(a, b):
        if a == "0":
            return b
        if b == "0":
            return a
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        res = []
        while i >= 0 or j >= 0 or carry:
            da = ord(a[i]) - 48 if i >= 0 else 0
            db = ord(b[j]) - 48 if j >= 0 else 0
            total = da + db + carry
            res.append(chr(total % 10 + 48))
            carry = total // 10
            i -= 1
            j -= 1
        res.reverse()
        return ''.join(res)

    @staticmethod
    def _sub_abs(a, b):
        if a == b:
            return "0"
        i, j = len(a) - 1, len(b) - 1
        borrow = 0
        res = []
        while i >= 0:
            da = ord(a[i]) - 48
            db = ord(b[j]) - 48 if j >= 0 else 0
            diff = da - db - borrow
            if diff < 0:
