                borrow = 1
            else:
                borrow = 0
            res.append(chr(diff + 48))
            i -= 1
            j -= 1
        while len(res) > 1 and res[-1] == '0':
            res.pop()
        res.reverse()
        return ''.join(res)

    @staticmethod
    def _mul_abs(a, b):
        if a == "0" or b == "0":
            return "0"
        n, m = len(a), len(b)
        res = [0] * (n + m)
        for i in range(n - 1, -1, -1):
            ai = ord(a[i]) - 48
            carry = 0
            for j in range(m - 1, -1, -1):
                bj = ord(b[j]) - 48
                total = ai * bj + res[i + j + 1] + carry
                res[i + j + 1] = total % 10
                carry = total // 10
            res[i] += carry
        start = 0
        while start < len(res) - 1 and res[start] == 0:
            start += 1
        return ''.join(chr(d + 48) for d in res[start:])

