        for movie in self.movies:
            if movie['name'] == name:
                seats = movie['seats']
                rows, cols = seats.shape
                seen = set()

                for seat in seats_to_book:
                    r, c = seat
                    if not (0 <= r < rows and 0 <= c < cols):
                        return 'Booking failed.'
                    if (r, c) in seen:
                        return 'Booking failed.'
                    seen.add((r, c))
                    if seats[r, c] != 0:
                        return 'Booking failed.'

                for r, c in seats_to_book:
                    seats[r, c] = 1

                return 'Booking success.'

        return 'Movie not found.'

