class BigNumCalculator:
    """
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    """

    @staticmethod
    def add(num1, num2):
        """
        Adds two big numbers.
        :param num1: The first number to add,str.
        :param num2: The second number to add,str.
        :return: The sum of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'
        """
        sign1, d1 = BigNumCalculator._normalize(num1)
        sign2, d2 = BigNumCalculator._normalize(num2)
        if sign1 == sign2:
            res = BigNumCalculator._add_abs(d1, d2)
            sign = sign1
        else:
            cmp = BigNumCalculator._compare_abs(d1, d2)
            if cmp == 0:
                return "0"
            if cmp > 0:
                res = BigNumCalculator._sub_abs(d1, d2)
                sign = sign1
            else:
                res = BigNumCalculator._sub_abs(d2, d1)
                sign = sign2
        return BigNumCalculator._format(sign, res)

    @staticmethod
    def subtract(num1, num2):
        """
        Subtracts two big numbers.
        :param num1: The first number to subtract,str.
        :param num2: The second number to subtract,str.
        :return: The difference of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'
        """
        sign1, d1 = BigNumCalculator._normalize(num1)
        sign2, d2 = BigNumCalculator._normalize(num2)
        if sign1 != sign2:
            res = BigNumCalculator._add_abs(d1, d2)
            sign = sign1
        else:
            cmp = BigNumCalculator._compare_abs(d1, d2)
            if cmp == 0:
                return "0"
            if cmp > 0:
                res = BigNumCalculator._sub_abs(d1, d2)
                sign = sign1
            else:
                res = BigNumCalculator._sub_abs(d2, d1)
                sign = -sign1
        return BigNumCalculator._format(sign, res)

    @staticmethod
    def multiply(num1, num2):
        """
        Multiplies two big numbers.
        :param num1: The first number to multiply,str.
        :param num2: The second number to multiply,str.
        :return: The product of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'
        """
        sign1, d1 = BigNumCalculator._normalize(num1)
        sign2, d2 = BigNumCalculator._normalize(num2)
        sign = sign1 * sign2
        res = BigNumCalculator._mul_abs(d1, d2)
        if res == "0":
            return "0"
        return BigNumCalculator._format(sign, res)

    @staticmethod
    def _normalize(num):
        num = num.strip()
        if not num:
            return 1, "0"
        sign = 1
        if num[0] == '-':
            sign = -1
            num = num[1:]
        elif num[0] == '+':
            num = num[1:]
        num = num.lstrip('0')
        if not num:
            return 1, "0"
        return sign, num

    @staticmethod
    def _compare_abs(a, b):
        if len(a) != len(b):
            return 1 if len(a) > len(b) else -1
        if a == b:
            return 0
        return 1 if a > b else -1

    @staticmethod
    def _add_abs(a, b):
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        res = []
        while i >= 0 or j >= 0 or carry:
            total = carry
            if i >= 0:
                total += int(a[i])
                i -= 1
            if j >= 0:
                total += int(b[j])
                j -= 1
            res.append(str(total % 10))
            carry = total // 10
        return ''.join(reversed(res)) or "0"

    @staticmethod
    def _sub_abs(a, b):
        # assumes a >= b
        i, j = len(a) - 1, len(b) - 1
        borrow = 0
        res = []
        while i >= 0:
            digit_a = int(a[i]) - borrow
            digit_b = int(b[j]) if j >= 0 else 0
            if digit_a < digit_b:
                digit_a += 10
                borrow = 1
            else:
                borrow = 0
            res.append(str(digit_a - digit_b))
            i -= 1
            j -= 1
        while len(res) > 1 and res[-1] == '0':
            res.pop()
        return ''.join(reversed(res)) or "0"

    @staticmethod
    def _mul_abs(a, b):
