        new_state = [row[:] for row in state]

        if direction == 'up':
            if i == 0:
                raise ValueError("Invalid move: up")
            new_state[i][j], new_state[i - 1][j] = new_state[i - 1][j], new_state[i][j]
        elif direction == 'down':
            if i == 2:
                raise ValueError("Invalid move: down")
            new_state[i][j], new_state[i + 1][j] = new_state[i + 1][j], new_state[i][j]
        elif direction == 'left':
            if j == 0:
                raise ValueError("Invalid move: left")
            new_state[i][j], new_state[i][j - 1] = new_state[i][j - 1], new_state[i][j]
        elif direction == 'right':
            if j == 2:
                raise ValueError("Invalid move: right")
            new_state[i][j], new_state[i][j + 1] = new_state[i][j + 1], new_state[i][j]
        else:
            raise ValueError(f"Invalid direction: {direction}")

        return new_state

    def get_possible_moves(self, state):
        i, j = self.find_blank(state)
        moves = []

        if i > 0:
            moves.append('up')
        if i < 2:
            moves.append('down')
        if j > 0:
            moves.append('left')
        if j < 2:
            moves.append('right')

        return moves

    def solve(self):
        start = tuple(tuple(row) for row in self.initial_state)
        goal = tuple(tuple(row) for row in self.goal_state)

        if start == goal:
            return []

        queue = deque()
        queue.append((self.initial_state, []))
        visited = {start}

        while queue:
            state, path = queue.popleft()

            for direction in self.get_possible_moves(state):
                new_state = self.move(state, direction)
                new_tuple = tuple(tuple(row) for row in new_state)

                if new_tuple in visited:
                    continue

                new_path = path + [direction]

                if new_tuple == goal:
                    return new_path

                visited.add(new_tuple)
                queue.append((new_state, new_path))

